app.get("/api/dm/threads/:thread_id/messages", async (req, res) => {
  noStore(res);
  try {
    const user = await getSessionUser(req).catch(() => null);
    if (!user || !user.id) return res.status(401).json({ ok: false, code: "AUTH_REQUIRED" });
    await ensurePersonMvTables();
    const tid = String(req.params.thread_id || "").trim();
    if (!/^[0-9a-fA-F-]{36}$/.test(tid)) return res.status(400).json({ ok: false, code: "INVALID_THREAD" });
    const acc = await dmThreadAccess(user.id, tid);
    if (!acc) return res.status(404).json({ ok: false, code: "NOT_FOUND" });
    const before = String(req.query.before || "").trim();
    const limit = Math.max(1, Math.min(100, Number(req.query.limit || 50) || 50));
    const params: Array<string | number> = [tid];
    let beforeClause = "";
    if (before && /^\d+$/.test(before)) {
      params.push(Number(before));
      beforeClause = ` AND message_id < $${params.length}`;
    }
    params.push(limit);
    const r = await withClient((c) =>
      c.query<{ message_id: string; sender_id: string; body: string; created_at: string }>(
        `SELECT message_id::text AS message_id, sender_id::text AS sender_id,
                body, created_at
           FROM dm_messages
          WHERE thread_id = $1::uuid${beforeClause}
          ORDER BY message_id DESC
          LIMIT $${params.length}`,
        params,
      ),
    );
    return res.json({
      ok: true,
      messages: r.rows.reverse().map((m) => ({
        message_id: m.message_id,
        sender_id: m.sender_id,
        body: m.body,
        created_at: m.created_at,
      })),
    });
  } catch (err) {
    return res.status(500).json({ ok: false, code: "DM_MESSAGES_FAILED", message: String(err) });
  }
});

app.post("/api/dm/threads/:thread_id/messages", express.json({ limit: "16kb" }), async (req, res) => {
  noStore(res);
  try {
    const user = await getSessionUser(req).catch(() => null);
    if (!user || !user.id) return res.status(401).json({ ok: false, code: "AUTH_REQUIRED" });
    await ensurePersonMvTables();
    const tid = String(req.params.thread_id || "").trim();
    if (!/^[0-9a-fA-F-]{36}$/.test(tid)) return res.status(400).json({ ok: false, code: "INVALID_THREAD" });
    const body = String((req.body && req.body.body) || "").trim();
    if (!body) return res.status(400).json({ ok: false, code: "EMPTY_BODY" });
    if (body.length > DM_BODY_MAX) {
      return res.status(400).json({ ok: false, code: "BODY_TOO_LONG", max: DM_BODY_MAX });
    }
    {
      const rl = await rateLimitCheck({
        key: `dm:${user.id}`,
        windowMs: 60_000,
        max: DM_RATE_PER_MIN,
      });
      if (!rl.ok) {
        const retry = Math.max(1, Math.ceil((rl.retryAfterMs || 1000) / 1000));
        res.setHeader("Retry-After", String(retry));
        return res.status(429).json({ ok: false, code: "RATE_LIMITED", retry_after: retry });
      }
    }
    // CSSOS_PERSON_MV_WAVE76 — daily DM cap (50/day) lifted for premium.
    const DM_DAILY_CAP = 50;
    const premium = await isPremium(user.id);
    if (!premium) {
      const sentToday = await withClient((c) =>
        c.query<{ n: string }>(
          `SELECT COUNT(*) AS n FROM dm_messages
            WHERE sender_id = $1::uuid AND created_at > now() - interval '24 hours'`,
          [user.id],
        ),
      );
      if (Number(sentToday.rows[0]?.n || 0) >= DM_DAILY_CAP) {
        return res.status(429).json({ ok: false, code: "DAILY_DM_CAP", cap: DM_DAILY_CAP, premium_required: true });
      }
    }
    const acc = await dmThreadAccess(user.id, tid);
    if (!acc) return res.status(404).json({ ok: false, code: "NOT_FOUND" });
    // Pair: per-recipient block check. Group: skip block check (membership already gates access).
    let recipients: string[] = [];
    if (acc.kind === "pair") {
      const otherId = acc.user_a_id === user.id ? acc.user_b_id! : acc.user_a_id!;
      if (await dmIsBlocked(user.id, otherId)) {
        return res.status(403).json({ ok: false, code: "BLOCKED" });
      }
      recipients = [otherId];
    } else {
      // CSSOS_PERSON_MV_WAVE67 — group fan-out: notify all members except sender.
      const all = await dmGroupMemberIds(tid);
      recipients = all.filter((u) => u !== user.id);
    }
    const ins = await withClient((c) =>
      c.query<{ message_id: string; created_at: string }>(
        `INSERT INTO dm_messages (thread_id, sender_id, body)
           VALUES ($1::uuid, $2::uuid, $3)
         RETURNING message_id::text AS message_id, created_at`,
        [tid, user.id, body],
      ),
    );
    if (acc.kind === "pair") {
      const sideCol = acc.side === "a" ? "a_last_read_at" : "b_last_read_at";
      await withClient((c) =>
        c.query(
          `UPDATE dm_threads
              SET last_message_at = now(), ${sideCol} = now()
            WHERE thread_id = $1::uuid`,
          [tid],
        ),
      );
    } else {
      await withClient((c) =>
        c.query(`UPDATE dm_threads SET last_message_at = now() WHERE thread_id = $1::uuid`, [tid]),
      );
      await withClient((c) =>
        c.query(
          `UPDATE dm_group_members SET last_read_at = now()
            WHERE thread_id = $1::uuid AND user_id = $2::uuid`,
          [tid, user.id],
        ),
      );
    }
    const msg = ins.rows[0];
    if (!msg) return res.status(500).json({ ok: false, code: "DM_SEND_FAILED" });
    // WebSocket fan-out — subscribers on /ws/dm/:thread_id (pair: both; group: all members).
    try {
      (globalThis as any).__cssosWsPublish?.("dm", tid, {
        kind: "dm_message",
        thread_id: tid,
        message_id: msg.message_id,
        sender_id: user.id,
        body,
        created_at: msg.created_at,
      });
    } catch { /* ignore */ }
    // Notification + webhook fan-out to all recipients.
    for (const rid of recipients) {
      void enqueueNotification(rid, "dm_received", {
        actor_id: user.id,
        actor_name: user.display_name || null,
        thread_id: tid,
        body: body.slice(0, 120),
        title: acc.kind === "group" ? (acc.title || "New group message") : "New message",
      }).catch(() => {});
    }
    return res.json({
      ok: true,
      message: {
        message_id: msg.message_id,
        sender_id: user.id,
        body,
        created_at: msg.created_at,
      },
    });
  } catch (err) {
    return res.status(500).json({ ok: false, code: "DM_SEND_FAILED", message: String(err) });
  }
});

