/* CSSOS_PERSON_MV_WAVE20 20260508 — Jing
 * Cap stored notifications per user at 1000. Run periodically to keep
 * the table from growing unboundedly for power-users. */
async function pruneOldNotifications(maxPerUser = 1000): Promise<number> {
  if (!DATABASE_URL) return 0;
  try {
    const r = await withClient((c) =>
      c.query<{ count: number }>(
        `WITH ranked AS (
           SELECT id,
                  row_number() OVER (PARTITION BY user_id ORDER BY created_at DESC) AS rn
             FROM user_notifications
         ),
         victims AS (
           SELECT id FROM ranked WHERE rn > $1
         ),
         deleted AS (
           DELETE FROM user_notifications WHERE id IN (SELECT id FROM victims) RETURNING 1
         )
         SELECT count(*)::int AS count FROM deleted`,
        [maxPerUser],
      ),
    );
    return Number(r.rows[0]?.count || 0);
  } catch (err) {
    console.warn("[notifications] prune failed:", (err as Error)?.message || err);
    return 0;
  }
}

/* CSSOS_PERSON_MV_WAVE29 20260508 — Jing
 * Creator credit ledger. awardCredit() inserts a credit_events row and
 * upserts user_credits.balance + lifetime_earned/spent atomically. View-
 * threshold awards collide on the unique partial index so re-firing the
 * same threshold is a no-op (returns awarded=false). Also drops a
 * `credit_awarded` notification so the bell surfaces it. */
export type CreditReason =
  | "mv_view_threshold"
  | "fork_received"
  | "use_received"
  | "spend"
  | "manual"
  | "upscale_spend"
  | "upscale_refund"
  | "product_click_reward"
  | "signup_bonus"
  | "referral_commission"
  | "remix_received";

async function awardCredit(
  userId: string | null | undefined,
  delta: number,
  reason: CreditReason,
  payload: Record<string, unknown> = {},
): Promise<{ awarded: boolean; balance: number }> {
  if (!DATABASE_URL || !userId || !Number.isFinite(delta) || delta === 0) {
    return { awarded: false, balance: 0 };
  }
  try {
    const ins = await withClient((c) =>
      c.query<{ id: string }>(
        `INSERT INTO credit_events (user_id, delta, reason, payload)
         VALUES ($1, $2, $3, $4::jsonb)
         ON CONFLICT ON CONSTRAINT credit_events_view_threshold_uidx DO NOTHING
         RETURNING id`,
        [userId, Math.trunc(delta), reason, JSON.stringify(payload || {})],
      ),
    );
    if (!ins.rowCount) {
      // Threshold dedup hit — already awarded.
      const cur = await withClient((c) =>
        c.query<{ balance: number }>(
          `SELECT balance FROM user_credits WHERE user_id = $1`,
          [userId],
        ),
      );
      return { awarded: false, balance: Number(cur.rows[0]?.balance ?? 0) };
    }
    const earnedDelta = delta > 0 ? delta : 0;
    const spentDelta = delta < 0 ? -delta : 0;
    const upd = await withClient((c) =>
      c.query<{ balance: number }>(
        `INSERT INTO user_credits (user_id, balance, lifetime_earned, lifetime_spent, updated_at)
         VALUES ($1, $2, $3, $4, now())
         ON CONFLICT (user_id) DO UPDATE
            SET balance = user_credits.balance + EXCLUDED.balance,
                lifetime_earned = user_credits.lifetime_earned + EXCLUDED.lifetime_earned,
                lifetime_spent = user_credits.lifetime_spent + EXCLUDED.lifetime_spent,
                updated_at = now()
         RETURNING balance`,
        [userId, Math.trunc(delta), earnedDelta, spentDelta],
      ),
    );
    const balance = Number(upd.rows[0]?.balance ?? 0);
    if (delta > 0) {
      await enqueueNotification(userId, "system", {
        ...(payload || {}),
        kind_subtype: "credit_awarded",
        delta,
        reason,
        balance,
      });
    }
    return { awarded: true, balance };
  } catch (err) {
    // Unique-violation on concurrent threshold = idempotent no-op.
    const msg = (err as Error)?.message || String(err);
    if (/duplicate key|unique/i.test(msg)) {
      return { awarded: false, balance: 0 };
    }
    console.warn("[credits] award failed:", msg);
    return { awarded: false, balance: 0 };
  }
}

// View-threshold ladder for awarding creator credits. Crossing each
// step awards +1 credit (idempotent via unique partial index).
const CREDIT_VIEW_THRESHOLDS = [100, 500, 1000, 5000, 10000];
function viewThresholdsCrossed(prev: number, next: number): number[] {
  return CREDIT_VIEW_THRESHOLDS.filter((t) => prev < t && next >= t);
}

// CSSOS_PERSON_MV_WAVE15 20260508 — Jing
// Defensively parse a free-form `lifespan` string and extract birth + death
// month-day (MM-DD). Handles English ("1879-03-14 – 1955-04-18"),
// Chinese with era prefixes ("公元前551年9月28日—前479年4月11日"),
// year-only ("公元1452-1519"), and partial/unparseable strings.
// Returns { birth: "MM-DD" | null, death: "MM-DD" | null } — null where
// no full month-day is present, so backfill skips those rows cleanly.
export function parseLifespanMonthDay(lifespan: string | null | undefined): { birth: string | null; death: string | null } {
  if (!lifespan || typeof lifespan !== "string") return { birth: null, death: null };
  const s = lifespan.trim();
  if (!s) return { birth: null, death: null };
  // Split on common dash separators.
  const sep = /[–—‐−\-\/~]|至|到|—|–/;
  // Take the first separator that splits into two non-empty halves.
  let parts: string[] = [];
  for (let i = 1; i < s.length - 1; i++) {
    if (sep.test(s.charAt(i))) {
      const left = s.slice(0, i).trim();
      const right = s.slice(i + 1).trim();
      if (left && right) { parts = [left, right]; break; }
    }
  }
  if (parts.length !== 2) parts = [s, ""];
  const extractMd = (chunk: string): string | null => {
    if (!chunk) return null;
    // Chinese form: N月N日
    const cn = chunk.match(/(\d{1,2})\s*月\s*(\d{1,2})\s*日/);
    if (cn && cn[1] && cn[2]) {
      const m = parseInt(cn[1], 10), d = parseInt(cn[2], 10);
      if (m >= 1 && m <= 12 && d >= 1 && d <= 31) return `${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
    }
    // ISO-ish: YYYY-MM-DD or -MM-DD
    const iso = chunk.match(/(?:^|[^\d])(\d{4})-(\d{1,2})-(\d{1,2})(?:[^\d]|$)/);
    if (iso && iso[2] && iso[3]) {
      const m = parseInt(iso[2], 10), d = parseInt(iso[3], 10);
      if (m >= 1 && m <= 12 && d >= 1 && d <= 31) return `${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
    }
    // MM/DD or M/D after a year
    const slash = chunk.match(/(\d{1,2})[\/\.](\d{1,2})(?:[^\d]|$)/);
    if (slash && slash[1] && slash[2]) {
      const m = parseInt(slash[1], 10), d = parseInt(slash[2], 10);
      if (m >= 1 && m <= 12 && d >= 1 && d <= 31) return `${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
    }
    return null;
  };
  return { birth: extractMd(parts[0] || ""), death: extractMd(parts[1] || "") };
}

let __personMdBackfilled = false;
async function backfillPersonMonthDayOnce() {
  if (__personMdBackfilled || !DATABASE_URL) return;
  __personMdBackfilled = true;
  try {
    const r = await withClient((c) =>
      c.query<{ person_id: string; lifespan: string | null }>(
        `SELECT person_id, lifespan FROM person_profiles
          WHERE lifespan IS NOT NULL
            AND birth_month_day IS NULL
            AND death_month_day IS NULL`,
      ),
    );
    for (const row of r.rows) {
      const { birth, death } = parseLifespanMonthDay(row.lifespan || "");
      if (!birth && !death) continue;
      await withClient((c) =>
        c.query(
          `UPDATE person_profiles SET birth_month_day = $2, death_month_day = $3
             WHERE person_id = $1
               AND birth_month_day IS NULL
               AND death_month_day IS NULL`,
          [row.person_id, birth, death],
        ),
      );
    }
  } catch (err) {
    console.warn("[person-mv] wave15 month-day backfill failed:", (err as Error)?.message || err);
  }
}

