/* CSSOS_PERSON_MV_WAVE24 20260508 — Jing — AI creator chat.
 * Single-shot intent extraction; chunked-transfer heartbeats during LLM
 * latency. Does NOT auto-execute irreversible actions; frontend triggers
 * person creation + cinema after receiving action="create_mv".
 * CSSOS_PERSON_MV_WAVE47 — long-term memory layered on top. */
app.post("/api/person-mv/ai-assistant", express.json({ limit: "8kb" }), async (req, res) => {
  noStore(res);
  try {
    const message = String((req.body as any)?.message || "").trim();
    if (!message) return res.status(400).json({ ok: false, code: "MESSAGE_REQUIRED" });
    if (message.length > 600) return res.status(400).json({ ok: false, code: "MESSAGE_TOO_LONG" });

    // CSSOS_PERSON_MV_WAVE47 — load memory if signed in.
    const me = await getSessionUser(req).catch(() => null);
    const mem = (me && me.id)
      ? await loadAiChatMemory(me.id)
      : { preferences: {} as AiChatPreferences, recent: [] as AiChatTurn[] };
    const memPrefs: AiChatPreferences = mem.preferences || {};
    const memRecent: AiChatTurn[] = mem.recent || [];

    res.status(200);
    res.setHeader("content-type", "application/json; charset=utf-8");
    res.setHeader("transfer-encoding", "chunked");
    res.flushHeaders?.();
    const heartbeat = setInterval(() => { try { res.write(" "); } catch {} }, 5000);

    const memoryContext = (me && me.id) ? (
      "\n--- User profile context ---\n" +
      `User favorite styles: ${(memPrefs.favorite_styles || []).join(", ") || "(none yet)"}\n` +
      `User favorite persons: ${(memPrefs.favorite_persons || []).join(", ") || "(none yet)"}\n` +
      `User language: ${memPrefs.language_pref || "auto-detect"}\n` +
      `Persona summary: ${memPrefs.persona_summary || "(unknown)"}\n` +
      `Recent context (last ${Math.min(memRecent.length, 6)} turns):\n` +
      memRecent.slice(-6).map((t) => `${t.role}: ${t.content}`).join("\n") +
      "\n--- end context ---\n"
    ) : "";

    const sysPrompt = memoryContext +
      "You are a music video creation assistant for CSS Studio. " +
      "Extract user intent and respond ONLY with strict JSON (no prose) matching: " +
      "{\"action\":\"create_mv\"|\"search_person\"|\"chat\", " +
      "\"target_name\":string|null, \"occasion\":string|null, " +
      "\"style_hint\":string|null, \"message\":string|null}. " +
      "Rules: " +
      "(1) action='create_mv' when user wants to MAKE an MV for a specific person/relative " +
      "(e.g. '为我妈做支60大寿MV','送给苏格拉底的赛博朋克版'). target_name MUST be filled. " +
      "(2) action='search_person' when they ask to explore an existing figure without making one. " +
      "(3) action='chat' for everything else; fill `message` with a short warm reply " +
      "(zh if user wrote zh, else en, ≤80 chars). " +
      "(4) `occasion` captures festival/birthday/anniversary if mentioned. " +
      "(5) `style_hint` captures genre/mood (cyberpunk, 古风, lofi, etc).";

    let parsed: any = null;
    try {
      const llm = await callLlm({
        messages: [
          { role: "system", content: sysPrompt },
          { role: "user", content: message },
        ],
        temperature: 0.3,
        max_tokens: 220,
        response_format: { type: "json_object" },
      });
      if (llm.ok && llm.content) {
        try { parsed = JSON.parse(llm.content); } catch { parsed = null; }
      }
    } catch (err) {
      console.warn("[person-mv] ai-assistant llm threw:", (err as Error)?.message || err);
    }

    if (!parsed || typeof parsed !== "object") {
      parsed = { action: "chat", target_name: null, occasion: null, style_hint: null, message: "我在,告诉我你想为谁做一支 MV。" };
    }
    const action = ["create_mv", "search_person", "chat"].includes(String(parsed.action))
      ? String(parsed.action)
      : "chat";
    const out = {
      action,
      target_name: parsed.target_name ? String(parsed.target_name).slice(0, 80) : null,
      occasion: parsed.occasion ? String(parsed.occasion).slice(0, 80) : null,
      style_hint: parsed.style_hint ? String(parsed.style_hint).slice(0, 120) : null,
      message: parsed.message ? String(parsed.message).slice(0, 240) : null,
    };

    clearInterval(heartbeat);
    try { res.write(JSON.stringify({ ok: true, data: out })); } catch {}
    res.end();

    // CSSOS_PERSON_MV_WAVE47 — persist this turn + maybe refresh persona.
    if (me && me.id) {
      try {
        const aiReply = out.message || (out.action === "create_mv"
          ? `creating MV for ${out.target_name || ""}` : (out.action === "search_person"
            ? `opening codex for ${out.target_name || ""}` : ""));
        const now = Date.now();
        const updatedRecent: AiChatTurn[] = [
          ...memRecent,
          { role: "user" as const, content: message.slice(0, 600), ts: now },
          { role: "assistant" as const, content: String(aiReply).slice(0, 600), ts: now + 1 },
        ].slice(-AI_CHAT_MEMORY_TURN_CAP);

        // Best-effort language pref detect.
        const isZh = /[一-鿿]/.test(message);
        const updatedPrefs: AiChatPreferences = {
          ...memPrefs,
          language_pref: memPrefs.language_pref || (isZh ? "zh" : "en"),
        };
        // Inline favorite tracking from current intent.
        if (out.style_hint) {
          const styles = Array.from(new Set([...(memPrefs.favorite_styles || []), out.style_hint]));
          updatedPrefs.favorite_styles = styles.slice(-AI_CHAT_PREFERENCE_CAP);
        }
        if (out.target_name) {
          const persons = Array.from(new Set([...(memPrefs.favorite_persons || []), out.target_name]));
          updatedPrefs.favorite_persons = persons.slice(-AI_CHAT_PREFERENCE_CAP);
        }

        await saveAiChatMemory(me.id, updatedPrefs, updatedRecent);

        // Every Nth user-turn, refresh persona summary in background.
        const userTurns = updatedRecent.filter((t) => t.role === "user").length;
        if (userTurns > 0 && userTurns % AI_CHAT_PERSONA_REFRESH_EVERY === 0) {
          void refreshPersonaSummary(me.id, updatedRecent, updatedPrefs);
        }
      } catch (e) {
        console.warn("[wave47] persist turn failed:", (e as Error)?.message || e);
      }
    }
    return;
  } catch (err) {
    console.warn("[person-mv] ai-assistant failed:", (err as Error)?.message || err);
    try { return res.status(500).json({ ok: false, code: "AI_ASSISTANT_FAILED" }); } catch { return; }
  }
});

/* CSSOS_PERSON_MV_WAVE69 20260508 — Jing — Content plaza (TikTok-style feed).
 * Vertical infinite-scroll feed of public MVs ranked by composite score:
 *   score = 0.5*log10(view_count+1) + 0.3*log10(like_count+1)
 *         + 0.2 * 1/(1 + days_since_created)
 * Cursor-based pagination (score, mv_id). Optional ?style=<tag> filter
 * (Wave 21 style_tags). Filters out MVs created by users the caller has
 * blocked (Wave 40 user_blocks). 60s in-memory cache by cursor key. */
type PlazaCacheEntry = { at: number; body: unknown };
const __plazaCache: Map<string, PlazaCacheEntry> = new Map();
const PLAZA_CACHE_TTL_MS = 60_000;
app.get("/api/person-mv/plaza", async (req, res) => {
  noStore(res);
  try {
    await ensurePersonMvTables();
    const cursorRaw = String(req.query.cursor || "").trim();
    const limit = Math.max(1, Math.min(20, Number(req.query.limit || 10) || 10));
    const styleRaw = String(req.query.style || "").trim().toLowerCase();
    const style = /^[a-z0-9_-]{1,32}$/.test(styleRaw) ? styleRaw : "";
    let blockedFor = "";
    try {
      const me = await getSessionUser(req).catch(() => null);
      if (me?.id) blockedFor = String(me.id);
    } catch { /* anonymous ok */ }
    const cacheKey = `${cursorRaw}|${limit}|${style}|${blockedFor}`;
    const hit = __plazaCache.get(cacheKey);
    if (hit && Date.now() - hit.at < PLAZA_CACHE_TTL_MS) {
      return res.json({ ok: true, ...(hit.body as object), cached: true });
    }
    let cursorScore: number | null = null;
    let cursorMvId: string | null = null;
    if (cursorRaw) {
      const m = cursorRaw.match(/^([0-9.eE+-]+)_([0-9a-fA-F-]{8,})$/);
      if (m) {
        cursorScore = Number(m[1]);
        cursorMvId = m[2] || null;
      }
    }
    const params: unknown[] = [];
    let where = `pm.visibility = 'public' AND pm.approval_status = 'auto_published'`;
    if (style) {
      params.push(style);
      where += ` AND $${params.length} = ANY(pm.style_tags)`;
    }
    if (blockedFor) {
      params.push(blockedFor);
      where += ` AND NOT EXISTS (SELECT 1 FROM user_blocks ub
                 WHERE ub.blocker_id = $${params.length}::uuid
                   AND ub.blocked_id = pm.created_by_user_id)`;
    }
    const scoreExpr = `(
        0.5 * ln(GREATEST(pm.view_count, 0) + 1) / ln(10)
      + 0.3 * ln(GREATEST(pm.like_count, 0) + 1) / ln(10)
      + 0.2 * (1.0 / (1.0 + GREATEST(EXTRACT(EPOCH FROM (now() - pm.created_at)) / 86400.0, 0)))
    )`;
    let cursorClause = "";
    if (cursorScore != null && cursorMvId) {
      params.push(cursorScore);
      const sIdx = params.length;
      params.push(cursorMvId);
      const idIdx = params.length;
      cursorClause = ` AND (${scoreExpr} < $${sIdx}::float
        OR (${scoreExpr} = $${sIdx}::float AND pm.mv_id::text < $${idIdx}))`;
    }
    params.push(limit);
    const limIdx = params.length;
    const sql = `
      SELECT pm.mv_id::text AS mv_id,
             pm.person_id,
             pm.work_id,
             pm.style_tags,
             pm.view_count,
             pm.like_count,
             pm.created_at,
             pm.created_by_user_id::text AS creator_user_id,
             pp.name_zh,
             pp.name_en,
             pp.civilization,
             pp.portrait_url,
             u.handle           AS creator_handle,
             u.display_name     AS creator_display_name,
             w.title            AS work_title,
             w.cover_image,
             w.preview_image_url,
             w.preview_video_url,
             (SELECT wa.url FROM work_assets wa
               WHERE wa.work_id = pm.work_id AND wa.asset_type = 'final_mv'
               LIMIT 1) AS final_mv_url,
             ${scoreExpr} AS plaza_score
        FROM person_mvs pm
        JOIN person_profiles pp ON pp.person_id = pm.person_id
        LEFT JOIN user_works  w ON w.id = pm.work_id
        LEFT JOIN users       u ON u.id = pm.created_by_user_id
       WHERE ${where}${cursorClause}
       ORDER BY ${scoreExpr} DESC, pm.mv_id::text DESC
       LIMIT $${limIdx}::int`;
    const r = await withClient((c) => c.query<any>(sql, params));
    const items = r.rows.map((row) => ({
      mv_id: row.mv_id,
      person_id: row.person_id,
      work_id: row.work_id,
      style_tags: row.style_tags || [],
      view_count: Number(row.view_count) || 0,
      like_count: Number(row.like_count) || 0,
      created_at: row.created_at,
      score: Number(row.plaza_score) || 0,
      cover_image: row.cover_image || row.preview_image_url || row.portrait_url || null,
      final_mv_url: row.final_mv_url || row.preview_video_url || null,
      title: row.work_title || null,
      person: {
        person_id: row.person_id,
        name_zh: row.name_zh,
        name_en: row.name_en,
        civilization: row.civilization,
        portrait_url: row.portrait_url,
      },
      creator: row.creator_user_id ? {
        user_id: row.creator_user_id,
        handle: row.creator_handle || null,
        display_name: row.creator_display_name || null,
      } : null,
    }));
    const last = items.length ? items[items.length - 1] : null;
    const nextCursor = last && items.length === limit
      ? `${last.score.toFixed(8)}_${last.mv_id}`
      : null;
    const body = { items, next_cursor: nextCursor };
    __plazaCache.set(cacheKey, { at: Date.now(), body });
    if (__plazaCache.size > 200) {
      const oldest = __plazaCache.keys().next().value;
      if (oldest) __plazaCache.delete(oldest);
    }
    return res.json({ ok: true, ...body });
  } catch (err) {
    console.warn("[person-mv] plaza failed:", (err as Error)?.message || err);
    return res.status(500).json({ ok: false, code: "PLAZA_FAILED" });
  }
});

// CSSOS_PERSON_MV_WAVE21 20260508 — Jing — style playlist endpoints.
// /api/person-mv/playlists       → list all available style chips + counts
// /api/person-mv/playlists/style/:tag?limit=20 → MVs for that chip, hottest first
app.get("/api/person-mv/playlists", async (_req, res) => {
  noStore(res);
  try {
    const r = await withClient((c) =>
      c.query<{ tag: string; mv_count: number }>(
        `SELECT t AS tag, COUNT(*)::int AS mv_count
           FROM person_mvs pm, unnest(pm.style_tags) t
          WHERE pm.visibility = 'public'
            AND pm.approval_status = 'auto_published'
          GROUP BY t
          ORDER BY mv_count DESC, t`,
      ),
    );
    return res.json({ ok: true, data: { playlists: r.rows } });
  } catch (err) {
    console.warn("[person-mv] playlists list failed:", (err as Error)?.message || err);
    return res.status(500).json({ ok: false, code: "PLAYLISTS_FAILED" });
  }
});

app.get("/api/person-mv/playlists/style/:tag", async (req, res) => {
  noStore(res);
  try {
    const tag = String(req.params.tag || "").trim().toLowerCase();
    if (!tag || !/^[a-z0-9_-]{1,32}$/.test(tag)) {
      return res.status(400).json({ ok: false, code: "INVALID_TAG" });
    }
    const limit = Math.max(1, Math.min(50, Number(req.query.limit || 20) || 20));
    const r = await withClient((c) =>
      c.query<any>(
        `SELECT pm.mv_id, pm.work_id, pm.person_id, pm.style_tags,
                pm.view_count, pm.like_count,
                pp.name_zh, pp.name_en, pp.civilization, pp.era, pp.portrait_url,
                uw.title, uw.cover_image
           FROM person_mvs pm
           JOIN person_profiles pp ON pp.person_id = pm.person_id
           LEFT JOIN user_works uw ON uw.id = pm.work_id
          WHERE pm.visibility = 'public'
            AND pm.approval_status = 'auto_published'
            AND $1 = ANY(pm.style_tags)
          ORDER BY pm.view_count DESC NULLS LAST, pm.created_at DESC
          LIMIT $2`,
        [tag, limit],
      ),
    );
    return res.json({ ok: true, data: { tag, mvs: r.rows } });
  } catch (err) {
    console.warn("[person-mv] playlists/style failed:", (err as Error)?.message || err);
    return res.status(500).json({ ok: false, code: "PLAYLIST_FAILED" });
  }
});

