app.get("/api/user/export/:job_id/download", async (req, res) => {
  try {
    const user = await getSessionUser(req).catch(() => null);
    if (!user || !user.id) return res.status(401).json({ ok: false, code: "AUTH_REQUIRED" });
    await ensurePersonMvTables();
    const id = String(req.params.job_id || "").trim();
    if (!id) return res.status(400).json({ ok: false, code: "INVALID_ID" });
    const r = await withClient((c) =>
      c.query<any>(
        `SELECT user_id, status, expires_at FROM user_export_jobs WHERE job_id = $1::uuid`,
        [id],
      ),
    );
    const job = r.rows[0];
    if (!job || job.user_id !== user.id) return res.status(404).json({ ok: false, code: "NOT_FOUND" });
    if (job.status !== "done") return res.status(409).json({ ok: false, code: "NOT_READY", status: job.status });
    if (job.expires_at && new Date(job.expires_at).getTime() < Date.now()) {
      return res.status(410).json({ ok: false, code: "EXPIRED" });
    }
    const file = path.join(exportRootDir(), `${user.id}-${id}.zip`);
    if (!fs.existsSync(file)) return res.status(410).json({ ok: false, code: "FILE_MISSING" });
    res.setHeader("Content-Type", "application/zip");
    res.setHeader("Content-Disposition", `attachment; filename="cssos-export-${id}.zip"`);
    fs.createReadStream(file).pipe(res);
    return;
  } catch (err) {
    return res.status(500).json({ ok: false, code: "EXPORT_DOWNLOAD_FAILED", message: String(err) });
  }
});

async function pruneExpiredExports(): Promise<number> {
  if (!DATABASE_URL) return 0;
  try {
    const r = await withClient((c) =>
      c.query<{ job_id: string; user_id: string }>(
        `SELECT job_id, user_id FROM user_export_jobs
          WHERE expires_at IS NOT NULL AND expires_at < now() AND status = 'done'`,
      ),
    );
    const root = exportRootDir();
    let removed = 0;
    for (const row of r.rows) {
      const f = path.join(root, `${row.user_id}-${row.job_id}.zip`);
      try { if (fs.existsSync(f)) { fs.unlinkSync(f); removed++; } } catch (_e) { /* ignore */ }
      await withClient((c) =>
        c.query(
          `UPDATE user_export_jobs SET status = 'expired', download_url = NULL, updated_at = now()
            WHERE job_id = $1`,
          [row.job_id],
        ),
      );
    }
    return removed;
  } catch (err) {
    console.warn("[export] prune failed:", (err as Error)?.message || err);
    return 0;
  }
}

/* CSSOS_PERSON_MV_WAVE39 20260508 — Jing — @mention extractor.
 * Pulls @username tokens from comment bodies. 2-32 chars,
 * letters/digits/underscore/hyphen, deduped + lowercased. */
function extractMentions(body: string): string[] {
  const out = new Set<string>();
  const re = /@([a-zA-Z0-9_-]{2,32})/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(String(body || ""))) !== null) {
    const handle: string | undefined = m[1];
    if (handle) out.add(handle.toLowerCase());
  }
  return Array.from(out);
}

/* CSSOS_PERSON_MV_WAVE12 20260508 — Jing — comments + share. */
function escapeHtmlBody(s: string): string {
  return String(s || "")
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

app.get("/api/person-mv/mvs/:mv_id/comments", async (req, res) => {
  noStore(res);
  try {
    await ensurePersonMvTables();
    const raw = String(req.params.mv_id || "").trim();
    const mvId = await resolvePersonMvId(raw);
    if (!mvId) return res.status(404).json({ ok: false, code: "NOT_FOUND" });
    const limit = Math.min(200, Math.max(1, parseInt(String(req.query.limit || "50"), 10) || 50));
    // CSSOS_PERSON_MV_WAVE40 — pull caller's blocklist so we can mask blocked authors.
    const me = await getSessionUser(req).catch(() => null);
    let blockedSet: Set<string> = new Set();
    if (me && me.id) {
      try {
        const br = await withClient((c) =>
          c.query<{ blocked_id: string }>(
            `SELECT blocked_id::text AS blocked_id FROM user_blocks WHERE blocker_id = $1`,
            [me.id],
          ),
        );
        blockedSet = new Set(br.rows.map((row) => row.blocked_id));
      } catch (_e) { /* non-fatal */ }
    }
    const r = await withClient((c) =>
      c.query(
        `SELECT c.id, c.mv_id, c.user_id, c.body, c.parent_id, c.created_at, c.deleted_at,
                u.display_name, u.username, u.avatar_url, u.verified_at
           FROM person_mv_comments c
           LEFT JOIN users u ON u.id = c.user_id
          WHERE c.mv_id = $1
          ORDER BY c.created_at ASC
          LIMIT $2`,
        [mvId, limit],
      ),
    );
    const items = r.rows
      .filter((row: any) => !blockedSet.has(String(row.user_id)))
      .map((row: any) => ({
      id: row.id,
      mv_id: row.mv_id,
      user_id: row.user_id,
      parent_id: row.parent_id,
      created_at: row.created_at,
      deleted: !!row.deleted_at,
      body_html: row.deleted_at ? null : (row.body ? escapeHtmlBody(row.body) : null),
      display_name: row.display_name,
      username: row.username,
      avatar_url: row.avatar_url,
      verified: !!row.verified_at,
      reactions: {} as Record<string, number>,
      my_reactions: [] as string[],
    }));
    // CSSOS_PERSON_MV_WAVE61 — bulk-load reactions for all comments in one query.
    if (items.length) {
      const ids = items.map((it) => it.id);
      try {
        const rxR = await withClient((c) =>
          c.query<{ comment_id: string; emoji: string; cnt: number }>(
            `SELECT comment_id::text, emoji, COUNT(*)::int AS cnt
               FROM comment_reactions
              WHERE comment_id = ANY($1::uuid[])
              GROUP BY comment_id, emoji`,
            [ids],
          ),
        );
        const byId: Record<string, Record<string, number>> = {};
        for (const row of rxR.rows) {
          (byId[row.comment_id] ||= {})[row.emoji] = row.cnt;
        }
        for (const it of items) it.reactions = byId[it.id] || {};
        if (me && me.id) {
          const myR = await withClient((c) =>
            c.query<{ comment_id: string; emoji: string }>(
              `SELECT comment_id::text, emoji
                 FROM comment_reactions
                WHERE comment_id = ANY($1::uuid[]) AND user_id = $2`,
              [ids, me.id],
            ),
          );
          const mineById: Record<string, string[]> = {};
          for (const row of myR.rows) {
            (mineById[row.comment_id] ||= []).push(row.emoji);
          }
          for (const it of items) it.my_reactions = mineById[it.id] || [];
        }
      } catch (_e) { /* non-fatal — table may not exist on cold boot */ }
    }
    // CSSOS_PERSON_MV_WAVE17 — include cached summary so the drawer can pin it.
    const sumR = await withClient((c) =>
      c.query<{ comment_summary: string | null; comment_summary_count: number; comment_summary_at: string | null }>(
        `SELECT comment_summary, comment_summary_count, comment_summary_at
           FROM person_mvs WHERE mv_id = $1`,
        [mvId],
      ),
    );
    const sum = sumR.rows[0] || null;
    return res.json({
      ok: true,
      items,
      summary: sum && sum.comment_summary ? {
        text: sum.comment_summary,
        count: sum.comment_summary_count,
        at: sum.comment_summary_at,
      } : null,
    });
  } catch (err) {
    return res.status(500).json({ ok: false, code: "COMMENTS_FAILED", message: String(err) });
  }
});

app.post("/api/person-mv/mvs/:mv_id/comments", express.json({ limit: "8kb" }), async (req, res) => {
  noStore(res);
  try {
    const user = await getSessionUser(req).catch(() => null);
    if (!user || !user.id) return res.status(401).json({ ok: false, code: "AUTH_REQUIRED" });
    await ensurePersonMvTables();
    const mvId = await resolvePersonMvId(String(req.params.mv_id || "").trim());
    if (!mvId) return res.status(404).json({ ok: false, code: "NOT_FOUND" });
    const body = String((req.body || {}).body || "").trim();
    if (!body) return res.status(400).json({ ok: false, code: "EMPTY_BODY" });
    if (body.length > 500) return res.status(400).json({ ok: false, code: "TOO_LONG" });
    const parentId = (req.body || {}).parent_id ? String((req.body || {}).parent_id) : null;
    const r = await withClient((c) =>
      c.query<{ id: string; created_at: string }>(
        `INSERT INTO person_mv_comments (mv_id, user_id, body, parent_id)
         VALUES ($1, $2, $3, $4)
         RETURNING id, created_at`,
        [mvId, user.id, body, parentId],
      ),
    );
    const row = r.rows[0];
    if (!row) return res.status(500).json({ ok: false, code: "COMMENT_POST_FAILED" });
    // CSSOS_PERSON_MV_WAVE20 — notify MV creator (skip self-comments).
    (async () => {
      try {
        const ownerR = await withClient((c) =>
          c.query<{ created_by_user_id: string; person_id: string }>(
            `SELECT created_by_user_id, person_id FROM person_mvs WHERE mv_id = $1`,
            [mvId],
          ),
        );
        const owner = ownerR.rows[0];
        if (owner && owner.created_by_user_id && owner.created_by_user_id !== user.id) {
          const actorR = await withClient((c) =>
            c.query<{ username: string | null; display_name: string | null }>(
              `SELECT username, display_name FROM users WHERE id = $1`,
              [user.id],
            ),
          );
          const actor = actorR.rows[0] || { username: null, display_name: null };
          await enqueueNotification(owner.created_by_user_id, "mv_comment", {
            actor_id: user.id,
            actor_username: actor.username,
            actor_name: actor.display_name || actor.username,
            mv_id: mvId,
            person_id: owner.person_id,
            comment_id: row.id,
            comment_body: body.slice(0, 200),
          });
        }
      } catch (_e) { /* non-fatal */ }
    })();
    // CSSOS_PERSON_MV_WAVE39 — @mention notifications. Skip self, blocked.
    (async () => {
      try {
        const handles = extractMentions(body);
        if (!handles.length) return;
        const ownerR = await withClient((c) =>
          c.query<{ created_by_user_id: string; person_id: string }>(
            `SELECT created_by_user_id, person_id FROM person_mvs WHERE mv_id = $1`,
            [mvId],
          ),
        );
        const owner = ownerR.rows[0] || { created_by_user_id: "", person_id: "" };
        const actorR = await withClient((c) =>
          c.query<{ username: string | null; display_name: string | null }>(
            `SELECT username, display_name FROM users WHERE id = $1`,
            [user.id],
          ),
        );
        const actor = actorR.rows[0] || { username: null, display_name: null };
        const usersR = await withClient((c) =>
          c.query<{ id: string; username: string }>(
            `SELECT id, username FROM users WHERE lower(username) = ANY($1::text[])`,
            [handles],
          ),
        );
        for (const u of usersR.rows) {
          if (!u.id || u.id === user.id) continue;
          const blocked = await withClient((c) =>
            c.query<{ x: number }>(
              `SELECT 1 AS x FROM user_blocks WHERE blocker_id = $1 AND blocked_id = $2 LIMIT 1`,
              [u.id, user.id],
            ),
          );
          if (blocked.rowCount && blocked.rowCount > 0) continue;
          await enqueueNotification(u.id, "comment_mention", {
            actor_id: user.id,
            actor_username: actor.username,
            actor_name: actor.display_name || actor.username,
            mv_id: mvId,
            person_id: owner.person_id,
            comment_id: row.id,
            snippet: body.slice(0, 200),
          });
        }
      } catch (_e) { /* non-fatal */ }
    })();
    // CSSOS_PERSON_MV_WAVE17 — fire-and-forget summary regen when count crosses
    // a threshold (10/20/50/100/250/500/1000). No await — never blocks reply.
    (async () => {
      try {
        const cR = await withClient((c) =>
          c.query<{ count: number; last: number }>(
            `SELECT
               (SELECT COUNT(*)::int FROM person_mv_comments
                  WHERE mv_id = $1 AND deleted_at IS NULL AND body IS NOT NULL) AS count,
               (SELECT comment_summary_count FROM person_mvs WHERE mv_id = $1) AS last`,
            [mvId],
          ),
        );
        const count = Number(cR.rows[0]?.count || 0);
        const last = Number(cR.rows[0]?.last || 0);
        if (shouldSummarizeAt(count, last)) {
          await runCommentSummary(mvId);
        }
      } catch (err) {
        console.warn("[person-mv] auto-summary failed:", (err as Error)?.message || err);
      }
    })();
    return res.json({
      ok: true,
      comment: {
        id: row.id,
        mv_id: mvId,
        user_id: user.id,
        parent_id: parentId,
        created_at: row.created_at,
        body_html: escapeHtmlBody(body),
        display_name: user.display_name,
        avatar_url: user.avatar_url,
      },
    });
  } catch (err) {
    return res.status(500).json({ ok: false, code: "COMMENT_POST_FAILED", message: String(err) });
  }
});

