app.post("/api/watch-parties/:id/events", express.json({ limit: "4kb" }), async (req, res) => {
  noStore(res);
  try {
    const user = await getSessionUser(req).catch(() => null);
    if (!user || !user.id) return res.status(401).json({ ok: false, code: "AUTH_REQUIRED" });
    await ensurePersonMvTables();
    const id = String(req.params.id || "").trim();
    if (!id) return res.status(400).json({ ok: false, code: "INVALID_ID" });
    const body = (req.body && typeof req.body === "object") ? req.body : {};
    const kind = String(body.kind || "").trim();
    if (!WATCH_PARTY_EVENT_KINDS.has(kind)) {
      return res.status(400).json({ ok: false, code: "INVALID_KIND" });
    }
    const partyR = await withClient((c) =>
      c.query<{ host_id: string }>(
        `SELECT host_id::text FROM watch_parties WHERE party_id = $1::uuid`,
        [id],
      ),
    );
    if (!partyR.rows[0]) return res.status(404).json({ ok: false, code: "NOT_FOUND" });
    const isHost = partyR.rows[0].host_id === user.id;
    // Only the host can drive playback.
    if ((kind === "play" || kind === "pause" || kind === "seek") && !isHost) {
      return res.status(403).json({ ok: false, code: "NOT_HOST" });
    }
    const payloadIn = body.payload && typeof body.payload === "object" ? body.payload : {};
    let payload: Record<string, any> = {};
    if (kind === "danmu") {
      // Wave 49 + Wave 103: danmu rate-limit (1/sec/user/party) now via unified helper.
      const rl = await rateLimitCheck({
        key: `danmu:${id}:${user.id}`,
        windowMs: 1000,
        max: 1,
      });
      if (!rl.ok) {
        const retry = Math.max(1, Math.ceil((rl.retryAfterMs || 1000) / 1000));
        res.setHeader("Retry-After", String(retry));
        return res.status(429).json({ ok: false, code: "RATE_LIMITED", retry_after: retry });
      }
      const text = String(payloadIn.text || "").trim();
      if (!text) return res.status(400).json({ ok: false, code: "EMPTY_TEXT" });
      if (text.length > 50) return res.status(400).json({ ok: false, code: "TOO_LONG" });
      payload = {
        user_id: user.id,
        text,
        color: typeof payloadIn.color === "string" ? String(payloadIn.color).slice(0, 16) : undefined,
        position: typeof payloadIn.position === "string" ? String(payloadIn.position).slice(0, 16) : undefined,
      };
    } else if (kind === "play" || kind === "pause" || kind === "seek") {
      const ct = Number(payloadIn.currentTime);
      payload = { currentTime: Number.isFinite(ct) ? ct : 0 };
    } else {
      payload = { user_id: user.id };
    }
    let payloadJson: string;
    try { payloadJson = JSON.stringify(payload); } catch { payloadJson = "{}"; }
    if (payloadJson.length > 3000) return res.status(400).json({ ok: false, code: "PAYLOAD_TOO_LARGE" });
    const ev = await withClient((c) =>
      c.query<{ id: string; created_at: string }>(
        `INSERT INTO watch_party_events (party_id, kind, user_id, payload)
         VALUES ($1::uuid, $2, $3::uuid, $4::jsonb)
         RETURNING id::text, created_at::text`,
        [id, kind, user.id, payloadJson],
      ),
    );
    // Wave 43: WS fan-out (best-effort).
    try {
      (globalThis as any).__cssosWsPublish?.("party", id, {
        id: ev.rows[0]?.id, kind, user_id: user.id, payload, created_at: ev.rows[0]?.created_at,
      });
    } catch { /* ignore */ }
    // Persist host playback state for late-joiners.
    if (isHost && (kind === "play" || kind === "pause" || kind === "seek")) {
      const playing = kind === "play";
      await withClient((c) =>
        c.query(
          `UPDATE watch_parties
              SET state = jsonb_build_object(
                'playing', $2::boolean,
                'currentTime', $3::numeric,
                'lastUpdated', $4::bigint
              )
            WHERE party_id = $1::uuid`,
          [id, kind === "seek" ? null : playing, payload.currentTime, Date.now()],
        ),
      );
    }
    if (kind === "join") {
      await withClient((c) =>
        c.query(
          `UPDATE watch_parties SET spectator_count = spectator_count + 1
            WHERE party_id = $1::uuid`,
          [id],
        ),
      );
    } else if (kind === "leave") {
      await withClient((c) =>
        c.query(
          `UPDATE watch_parties
              SET spectator_count = GREATEST(spectator_count - 1, 0)
            WHERE party_id = $1::uuid`,
          [id],
        ),
      );
    }
    return res.json({ ok: true, event_id: ev.rows[0]?.id });
  } catch (err) {
    return res.status(500).json({ ok: false, code: "WATCH_PARTY_EVENT_FAILED", message: String(err) });
  }
});

app.get("/api/watch-parties/:id/events", async (req, res) => {
  // Long-poll mirroring /api/live/rooms/:id/events: hold up to 25s,
  // chunked-transfer space heartbeats every 5s, 1.5s DB poll cadence.
  noStore(res);
  try {
    await ensurePersonMvTables();
    const id = String(req.params.id || "").trim();
    if (!id) return res.status(400).json({ ok: false, code: "INVALID_ID" });
    const since = Math.max(0, Number(req.query.since || 0) | 0);
    const exists = await withClient((c) =>
      c.query<{ party_id: string }>(
        `SELECT party_id::text FROM watch_parties WHERE party_id = $1::uuid`,
        [id],
      ),
    );
    if (!exists.rows[0]) return res.status(404).json({ ok: false, code: "NOT_FOUND" });

    const fetchSince = async (s: number) => {
      const r = await withClient((c) =>
        c.query<any>(
          `SELECT id::text, kind, user_id::text, payload, created_at::text
             FROM watch_party_events
            WHERE party_id = $1::uuid AND id > $2
            ORDER BY id ASC
            LIMIT 200`,
          [id, s],
        ),
      );
      return r.rows;
    };

    const initialRows = await fetchSince(since);
    if (initialRows.length > 0) {
      return res.json({ ok: true, events: initialRows });
    }

    res.status(200);
    res.setHeader("Content-Type", "application/json; charset=utf-8");
    res.setHeader("X-Accel-Buffering", "no");
    res.setHeader("Transfer-Encoding", "chunked");
    (res as any).flushHeaders?.();

    const startedAt = Date.now();
    const TIMEOUT_MS = 25_000;
    const HEARTBEAT_MS = 5_000;
    const POLL_INTERVAL_MS = 1500;
    let finished = false;
    let heartbeat: ReturnType<typeof setInterval> | null = null;
    let nextTick: ReturnType<typeof setTimeout> | null = null;
    const cleanup = () => {
      if (heartbeat) { clearInterval(heartbeat); heartbeat = null; }
      if (nextTick) { clearTimeout(nextTick); nextTick = null; }
    };
    const finish = (payload: any) => {
      if (finished) return;
      finished = true;
      cleanup();
      try { res.end(JSON.stringify(payload)); } catch { /* ignore */ }
    };
    heartbeat = setInterval(() => {
      if (finished) return;
      try { res.write(" "); } catch { /* client gone */ }
    }, HEARTBEAT_MS);

    const tick = async () => {
      nextTick = null;
      if (finished) return;
      if (Date.now() - startedAt >= TIMEOUT_MS) {
        return finish({ ok: true, events: [] });
      }
      try {
        const fresh = await fetchSince(since);
        if (fresh.length > 0) return finish({ ok: true, events: fresh });
      } catch (err) {
        return finish({ ok: false, code: "WATCH_PARTY_POLL_FAILED", message: String(err) });
      }
      if (!finished) nextTick = setTimeout(tick, POLL_INTERVAL_MS);
    };
    req.on("close", () => {
      finished = true;
      cleanup();
    });
    nextTick = setTimeout(tick, POLL_INTERVAL_MS);
    return;
  } catch (err) {
    if (!res.headersSent) {
      return res.status(500).json({ ok: false, code: "WATCH_PARTY_EVENTS_FAILED", message: String(err) });
    }
    return;
  }
});

/* CSSOS_PERSON_MV_WAVE41 20260508 — Jing — admin trends dashboard.
 * Four admin-only metrics endpoints powering the #admin/dashboard
 * panel: DAU line, top persons, engine cost bars, signup funnel. All
 * gated via roleForEmail()==='admin'. */

app.get("/api/admin/metrics/dau", async (req, res) => {
  noStore(res);
  try {
    const user = await getSessionUser(req);
    if (!user || roleForEmail(user.email) !== "admin") {
      return res.status(403).json({ ok: false, code: "FORBIDDEN" });
    }
    const days = Math.max(1, Math.min(180, Number(req.query.days || 7)));
    const interval = `${days} days`;
    const rows = await withClient((c) =>
      c.query<{ day: string; dau: string }>(
        `SELECT to_char(date_trunc('day', last_active_at), 'YYYY-MM-DD') AS day,
                COUNT(DISTINCT id)::text AS dau
           FROM users
          WHERE last_active_at IS NOT NULL
            AND last_active_at > now() - $1::interval
          GROUP BY day
          ORDER BY day`,
        [interval],
      ),
    );
    return res.json(
      okData({
        days,
        source: "users.last_active_at",
        series: rows.rows.map((r) => ({ day: r.day, dau: Number(r.dau) })),
      }),
    );
  } catch (err) {
    return res.status(500).json({
      ok: false,
      code: "ADMIN_DAU_FAILED",
      message: String((err as Error)?.message || err),
    });
  }
});

app.get("/api/admin/metrics/top-persons", async (req, res) => {
  noStore(res);
  try {
    const user = await getSessionUser(req);
    if (!user || roleForEmail(user.email) !== "admin") {
      return res.status(403).json({ ok: false, code: "FORBIDDEN" });
    }
    const limit = Math.max(1, Math.min(100, Number(req.query.limit || 20)));
    const period = String(req.query.period || "all").toLowerCase();
    const intervalSql =
      period === "week"
        ? "AND pm.created_at > now() - interval '7 days'"
        : period === "month"
        ? "AND pm.created_at > now() - interval '30 days'"
        : "";
    const rows = await withClient((c) =>
      c.query<any>(
        `SELECT pp.id::text AS id,
                pp.name_zh,
                pp.name_en,
                COALESCE(SUM(pm.view_count), 0)::int AS total_views,
                COUNT(pm.id)::int AS mv_count
           FROM person_profiles pp
           LEFT JOIN person_mvs pm
             ON pm.person_id = pp.id
            ${intervalSql}
          GROUP BY pp.id, pp.name_zh, pp.name_en
          ORDER BY total_views DESC NULLS LAST
          LIMIT $1`,
        [limit],
      ),
    );
    return res.json(
      okData({ period, limit, persons: rows.rows }),
    );
  } catch (err) {
    return res.status(500).json({
      ok: false,
      code: "ADMIN_TOP_PERSONS_FAILED",
      message: String((err as Error)?.message || err),
    });
  }
});

app.get("/api/admin/metrics/engine-costs", async (req, res) => {
  noStore(res);
  try {
    const user = await getSessionUser(req);
    if (!user || roleForEmail(user.email) !== "admin") {
      return res.status(403).json({ ok: false, code: "FORBIDDEN" });
    }
    const period = String(req.query.period || "week").toLowerCase();
    const intervalSql =
      period === "month"
        ? "30 days"
        : period === "day"
        ? "1 day"
        : "7 days";
    // Group by meta->>'engine' (preferred) or fallback to first
    // segment of route. Cents summed across all stages.
    const rows = await withClient((c) =>
      c.query<{ engine: string; cost_cents: string; events: string }>(
        `SELECT COALESCE(NULLIF(meta->>'engine',''),
                         NULLIF(meta->>'provider',''),
                         split_part(route,'/',3),
                         'unknown') AS engine,
                COALESCE(SUM(cost_cents), 0)::text AS cost_cents,
                COUNT(*)::text AS events
           FROM usage_events
          WHERE created_at > now() - $1::interval
          GROUP BY engine
          ORDER BY SUM(cost_cents) DESC NULLS LAST
          LIMIT 50`,
        [intervalSql],
      ),
    );
    return res.json(
      okData({
        period,
        engines: rows.rows.map((r) => ({
          engine: r.engine,
          cost_cents: Number(r.cost_cents),
          events: Number(r.events),
        })),
      }),
    );
  } catch (err) {
    return res.status(500).json({
      ok: false,
      code: "ADMIN_ENGINE_COSTS_FAILED",
      message: String((err as Error)?.message || err),
    });
  }
});

app.get("/api/admin/metrics/funnel", async (req, res) => {
  noStore(res);
  try {
    const user = await getSessionUser(req);
    if (!user || roleForEmail(user.email) !== "admin") {
      return res.status(403).json({ ok: false, code: "FORBIDDEN" });
    }
    const result = await withClient(async (c) => {
      // Visitors: distinct users who hit any usage_event in last 7d.
      // Falls back to total active users if usage_events is sparse.
      const visitorsRow = await c.query<{ n: string }>(
        `SELECT COUNT(DISTINCT user_id)::text AS n
           FROM usage_events
          WHERE created_at > now() - interval '7 days'
            AND user_id IS NOT NULL`,
      );
      const signupsRow = await c.query<{ n: string }>(
        `SELECT COUNT(*)::text AS n
           FROM users
          WHERE created_at > now() - interval '7 days'`,
      );
      const firstCreatorsRow = await c.query<{ n: string }>(
        `SELECT COUNT(DISTINCT owner_user_id)::text AS n
           FROM person_mvs
          WHERE created_at > now() - interval '7 days'
            AND owner_user_id IS NOT NULL`,
      );
      const repeatCreatorsRow = await c.query<{ n: string }>(
        `SELECT COUNT(*)::text AS n FROM (
           SELECT owner_user_id
             FROM person_mvs
            WHERE owner_user_id IS NOT NULL
            GROUP BY owner_user_id
           HAVING COUNT(*) >= 3
         ) t`,
      );
      return {
        visitors: Number(visitorsRow.rows[0]?.n || 0),
        signups: Number(signupsRow.rows[0]?.n || 0),
        first_mv_creators: Number(firstCreatorsRow.rows[0]?.n || 0),
        repeat_creators: Number(repeatCreatorsRow.rows[0]?.n || 0),
      };
    });
    const pct = (n: number, d: number) =>
      d > 0 ? Math.round((n / d) * 1000) / 10 : 0;
    return res.json(
      okData({
        ...result,
        conversions: {
          visitor_to_signup_pct: pct(result.signups, result.visitors),
          signup_to_first_creator_pct: pct(
            result.first_mv_creators,
            result.signups,
          ),
          first_to_repeat_creator_pct: pct(
            result.repeat_creators,
            result.first_mv_creators,
          ),
        },
      }),
    );
  } catch (err) {
    return res.status(500).json({
      ok: false,
      code: "ADMIN_FUNNEL_FAILED",
      message: String((err as Error)?.message || err),
    });
  }
});

/* CSSOS_WAVE80 20260508 — Jing — web-vitals telemetry.
 * POST /api/internal/webvitals  body {name,value,id,route}
 * GET  /api/admin/metrics/web-vitals  → p50/p75/p95 LCP/CLS/INP, last 24h. */
const WEB_VITAL_METRICS = new Set(["LCP", "CLS", "INP", "FID", "TTFB"]);
app.post("/api/internal/webvitals", async (req, res) => {
  noStore(res);
  try {
    const body = (req.body && typeof req.body === "object") ? req.body : {};
    const name = String((body as any).name || "").toUpperCase().slice(0, 8);
    const value = Number((body as any).value);
    const route = String((body as any).route || "").slice(0, 200) || null;
    if (!WEB_VITAL_METRICS.has(name) || !isFinite(value)) {
      return res.status(204).end();
    }
    const ua = String(req.get("user-agent") || "").slice(0, 400) || null;
    const userId = ((req as any).session && (req as any).session.user_id) || null;
    try {
      await withClient((c) =>
        c.query(
          `INSERT INTO web_vitals_samples (route, metric, value, ua, user_id)
           VALUES ($1, $2, $3, $4, $5::uuid)`,
          [route, name, value, ua, userId],
        ),
      );
    } catch (dbErr) {
      // Table may not exist yet on a fresh deploy — degrade gracefully.
      console.warn("[webvitals] insert failed:", String((dbErr as Error)?.message || dbErr));
    }
    if ((name === "LCP" && value > 4000) || (name === "INP" && value > 500)) {
      sentryBreadcrumb({
        category: "web-vitals",
        message: `slow ${name} ${Math.round(value)}ms`,
        data: { route, metric: name, value },
      });
    }
    return res.status(204).end();
  } catch {
    return res.status(204).end();
  }
});

