const VALID_REPORT_KINDS = new Set(["mv", "comment", "user", "person"]);
const VALID_REASON_CODES = new Set(["spam", "harassment", "copyright", "nsfw", "factual_error", "other"]);

// CSSOS_PERSON_MV_WAVE44 20260508 — Jing — LLM-assisted moderation.
// Pulls a short snippet of the reported content for context, then asks an
// LLM for a verdict. Fire-and-forget from the report POST handler.
async function fetchReportContentSnippet(kind: string, id: string): Promise<string> {
  try {
    if (kind === "mv") {
      const r = await withClient((c) =>
        c.query<{ snippet: string | null }>(
          `SELECT COALESCE(scenario_seed, '') AS snippet FROM person_mvs WHERE mv_id = $1::uuid`,
          [id],
        ),
      );
      return String(r.rows[0]?.snippet || "").slice(0, 800);
    }
    if (kind === "comment") {
      const r = await withClient((c) =>
        c.query<{ snippet: string | null }>(
          `SELECT COALESCE(body, '') AS snippet FROM person_mv_comments WHERE id = $1::uuid`,
          [id],
        ),
      );
      return String(r.rows[0]?.snippet || "").slice(0, 800);
    }
    if (kind === "person") {
      const r = await withClient((c) =>
        c.query<{ snippet: string | null }>(
          `SELECT COALESCE(name_zh, '') || ' ' || COALESCE(name_en, '') || ' ' || COALESCE(core_theme, '') AS snippet
             FROM person_profiles WHERE person_id = $1`,
          [id],
        ),
      );
      return String(r.rows[0]?.snippet || "").slice(0, 800);
    }
  } catch (_e) { /* best-effort */ }
  return "";
}

async function classifyReportLlm(
  reportId: string,
  reasonCode: string,
  targetKind: string,
  targetId: string,
): Promise<void> {
  try {
    const snippet = await fetchReportContentSnippet(targetKind, targetId);
    const prompt =
      `Classify this content report. The reporter says: ${reasonCode}. ` +
      `The reported content is: ${snippet || "(no snippet available)"}. ` +
      `Output strict JSON: {"verdict":"clear_violation"|"borderline"|"no_violation","confidence":0-1,"reasoning":"short explanation"}`;
    const llm = await callLlm({
      messages: [
        { role: "system", content: "You are a strict but fair content moderation classifier. Reply ONLY with the requested JSON." },
        { role: "user", content: prompt },
      ],
      temperature: 0.2,
      max_tokens: 200,
      response_format: { type: "json_object" },
    });
    if (!llm.ok || !llm.content) return;
    let parsed: any = null;
    try { parsed = JSON.parse(llm.content); } catch { return; }
    const verdict = ["clear_violation", "borderline", "no_violation"].includes(String(parsed?.verdict))
      ? String(parsed.verdict) : null;
    if (!verdict) return;
    const confidence = Math.max(0, Math.min(1, Number(parsed.confidence) || 0));
    const reasoning = String(parsed.reasoning || "").slice(0, 600);

    await withClient((c) =>
      c.query(
        `UPDATE content_reports
            SET llm_verdict = $1, llm_confidence = $2, llm_reasoning = $3
          WHERE report_id = $4::uuid`,
        [verdict, confidence, reasoning, reportId],
      ),
    );

    // Auto-action obvious violations.
    if (verdict === "clear_violation" && confidence > 0.8) {
      try {
        if (targetKind === "mv") {
          await withClient((c) =>
            c.query(`UPDATE user_works SET status = 'hidden_by_admin' WHERE work_id = $1::uuid`, [targetId]),
          ).catch(() => {});
        } else if (targetKind === "comment") {
          await withClient((c) =>
            c.query(`UPDATE person_mv_comments SET deleted_at = now() WHERE id = $1::uuid`, [targetId]),
          ).catch(() => {});
        }
        await withClient((c) =>
          c.query(
            `UPDATE content_reports
                SET status = 'resolved', auto_resolved_at = now()
              WHERE report_id = $1::uuid`,
            [reportId],
          ),
        );
      } catch (e) {
        console.warn("[wave44] auto-action failed:", (e as Error)?.message || e);
      }
    }
  } catch (err) {
    console.warn("[wave44] classifyReportLlm failed:", (err as Error)?.message || err);
  }
}

app.post("/api/reports", express.json({ limit: "8kb" }), async (req, res) => {
  noStore(res);
  try {
    const me = await getSessionUser(req).catch(() => null);
    if (!me || !me.id) return res.status(401).json({ ok: false, code: "AUTH_REQUIRED" });
    const body = req.body || {};
    const target_kind = String(body.target_kind || "").trim();
    const target_id = String(body.target_id || "").trim();
    const reason_code = String(body.reason_code || "").trim();
    const details = String(body.details || "").trim().slice(0, 2000) || null;
    if (!VALID_REPORT_KINDS.has(target_kind)) {
      return res.status(400).json({ ok: false, code: "BAD_TARGET_KIND" });
    }
    if (!target_id) return res.status(400).json({ ok: false, code: "BAD_TARGET_ID" });
    if (!VALID_REASON_CODES.has(reason_code)) {
      return res.status(400).json({ ok: false, code: "BAD_REASON" });
    }
    try {
      const r = await withClient((c) =>
        c.query<{ report_id: string }>(
          `INSERT INTO content_reports (reporter_id, target_kind, target_id, reason_code, details)
           VALUES ($1, $2, $3, $4, $5)
           RETURNING report_id::text`,
          [me.id, target_kind, target_id, reason_code, details],
        ),
      );
      const reportId = r.rows[0]?.report_id || null;
      // CSSOS_PERSON_MV_WAVE44 — fire-and-forget LLM classification.
      if (reportId) {
        void classifyReportLlm(reportId, reason_code, target_kind, target_id);
      }
      return res.json({ ok: true, report_id: reportId });
    } catch (e: any) {
      if (String(e?.code) === "23505") {
        return res.status(429).json({ ok: false, code: "ALREADY_REPORTED_TODAY" });
      }
      throw e;
    }
  } catch (err) {
    return res.status(500).json({ ok: false, code: "REPORT_FAILED", message: String(err) });
  }
});

app.get("/api/admin/reports", async (req, res) => {
  noStore(res);
  if (!(await isAdminRequest(req))) {
    return res.status(403).json({ ok: false, code: "FORBIDDEN" });
  }
  try {
    const status = String(req.query.status || "open");
    const limit = Math.max(1, Math.min(200, parseInt(String(req.query.limit || "50"), 10) || 50));
    const r = await withClient((c) =>
      c.query<any>(
        `SELECT report_id::text, reporter_id::text, target_kind, target_id, reason_code, details,
                status, reviewed_by::text AS reviewed_by, reviewed_at::text AS reviewed_at,
                created_at::text AS created_at,
                llm_verdict, llm_confidence, llm_reasoning,
                auto_resolved_at::text AS auto_resolved_at
           FROM content_reports
          WHERE status = $1
          ORDER BY created_at DESC
          LIMIT $2`,
        [status, limit],
      ),
    );
    return res.json({ ok: true, items: r.rows });
  } catch (err) {
    return res.status(500).json({ ok: false, code: "ADMIN_REPORTS_FAILED", message: String(err) });
  }
});

app.post("/api/admin/reports/:id/resolve", express.json({ limit: "2kb" }), async (req, res) => {
  noStore(res);
  if (!(await isAdminRequest(req))) {
    return res.status(403).json({ ok: false, code: "FORBIDDEN" });
  }
  try {
    const me = await getSessionUser(req).catch(() => null);
    if (!me || !me.id) return res.status(401).json({ ok: false, code: "AUTH_REQUIRED" });
    const id = String(req.params.id || "").trim();
    const action = String((req.body || {}).action || "").trim();
    if (!["dismiss", "hide", "ban"].includes(action)) {
      return res.status(400).json({ ok: false, code: "BAD_ACTION" });
    }
    const repR = await withClient((c) =>
      c.query<{ target_kind: string; target_id: string }>(
        `SELECT target_kind, target_id FROM content_reports WHERE report_id = $1::uuid`,
        [id],
      ),
    );
    const rep = repR.rows[0];
    if (!rep) return res.status(404).json({ ok: false, code: "NOT_FOUND" });

    if (action === "hide") {
      try {
        if (rep.target_kind === "mv") {
          await withClient((c) =>
            c.query(`UPDATE user_works SET status = 'hidden_by_admin' WHERE work_id = $1::uuid`, [rep.target_id]),
          ).catch(() => {});
        } else if (rep.target_kind === "comment") {
          await withClient((c) =>
            c.query(`UPDATE person_mv_comments SET deleted_at = now() WHERE id = $1::uuid`, [rep.target_id]),
          ).catch(() => {});
        }
      } catch (_e) { /* best-effort */ }
    } else if (action === "ban") {
      try {
        if (rep.target_kind === "user") {
          await withClient((c) =>
            c.query(`UPDATE users SET banned_at = now() WHERE id = $1::uuid`, [rep.target_id]),
          ).catch(() => {});
        }
      } catch (_e) { /* best-effort */ }
    }

    const newStatus = action === "dismiss" ? "dismissed" : "resolved";
    await withClient((c) =>
      c.query(
        `UPDATE content_reports SET status = $1, reviewed_by = $2, reviewed_at = now()
          WHERE report_id = $3::uuid`,
        [newStatus, me.id, id],
      ),
    );
    return res.json({ ok: true, status: newStatus });
  } catch (err) {
    return res.status(500).json({ ok: false, code: "RESOLVE_FAILED", message: String(err) });
  }
});

async function start() {
  const openAiRuntime = getOpenAiRuntimeConfig();
  console.info("[startup.openai]", {
    envSource: openAiRuntime.envSource,
    keyFingerprint: openAiRuntime.keyFingerprint || "missing",
    textModel: openAiRuntime.model,
    transcribeModel: getOpenAiTranscribeModel(),
  });
  if (DATABASE_URL) {
    try {
      await runMigrations();
      await ensureAuthIdentityTable();
      await ensureOAuthTokensTable();
      await processMatureSellerPayouts();
      const runPayoutSweepLoop = async () => {
        try {
          await processMatureSellerPayouts();
        } catch (err) {
          console.error("Payout sweep failed", err);
        } finally {
          const commerce = await getCommercePolicySettings().catch(() => ({
            payoutSweepMs: stripePayoutSweepMsEnv(),
          }));
          setTimeout(
            runPayoutSweepLoop,
            Number(commerce?.payoutSweepMs || stripePayoutSweepMsEnv()),
          );
        }
      };
      const commerce = await getCommercePolicySettings().catch(() => ({
        payoutSweepMs: stripePayoutSweepMsEnv(),
      }));
      setTimeout(
        runPayoutSweepLoop,
        Number(commerce?.payoutSweepMs || stripePayoutSweepMsEnv()),
      );
    } catch (err) {
      console.error(
        "Startup DB bootstrap failed; continuing in degraded mode",
        err,
      );
    }
  }
  // CSSOS_PHASE2_PERSONALIZATION_TEMPLATES 20260502 #270 - Jing
  // Boot the personalization engine: scan the templates directory
  // and register every gift trigger handler. Both calls are
  // idempotent and best-effort — failure here MUST NOT crash the
  // API. We log + continue so the rest of cssOS keeps serving even
  // if the gift system is misconfigured.
  try {
    const {
      loadPersonalizationTemplates,
      registerAllPersonalizationTriggers,
      runDailyBirthdayFlush,
      fireTriggerFireAndForget,
    } = await import("./personalization/index.js");
    await loadPersonalizationTemplates();
    registerAllPersonalizationTriggers();

    // CSSOS_PHASE2_PERSONALIZATION_STAGE_F 20260503 — Jing
    // Birthday flush daemon. Scans every 6 hours; the SQL inside
    // already de-dupes so users won't get the same year's birthday
    // MV twice even if the cron fires multiple times per local day.
    // Same-process scheduler (no external cron) keeps the
    // dependency surface minimal — runs exactly while the API is
    // up. The SQL also handles per-user timezones so a user in
    // UTC+8 is hit at the right local-day boundary regardless of
    // when the VM happens to fire.
    const SIX_HOURS_MS = 6 * 60 * 60 * 1000;
    const birthdayFlushTick = async () => {
      try {
        const userIds = await runDailyBirthdayFlush(
          getPool(),
          fireTriggerFireAndForget,
          getPool(),
        );
        if (userIds.length) {
          console.log(
            "[personalization] birthday flush dispatched %d gift(s)",
            userIds.length,
          );
        }
      } catch (e) {
        console.warn(
          "[personalization] birthday flush failed (non-fatal):",
          e instanceof Error ? e.message : String(e),
        );
      }
    };
    // Fire once shortly after boot (5 min — gives DB pool time to
    // warm up) so a deploy mid-day still catches the day's birthdays.
    setTimeout(birthdayFlushTick, 5 * 60 * 1000);
    setInterval(birthdayFlushTick, SIX_HOURS_MS);
  } catch (err) {
    console.error(
      "[personalization] engine boot failed; continuing without gifts —",
      err,
    );
  }

  /* CSSOS_PERSON_MV_WAVE13C 20260508 — Jing
   * Nightly auto sample-MV generator. Fires at 03:00 UTC daily so any
   * newly seeded (or ad-hoc) person without an official sample picks one
   * up overnight. Capped at 10/night so we don't burn engine credits in
   * one go; the admin endpoint can still pass higher limits manually.
   * Skipped in dev (no DATABASE_URL) so local boots don't hammer free
   * tiers. Same-process scheduler — no external cron required. */
  if (process.env.DATABASE_URL) {
    const ONE_DAY_MS = 24 * 60 * 60 * 1000;
    const cronTick = async () => {
      try {
        const summary = await generatePersonSamplesBatch({
          limit: 10,
          source: "cron",
        });
        console.log(
          `[cron-samples] tick ok — processed=${summary.processed} succeeded=${summary.succeeded} failed=${summary.failed}`,
        );
      } catch (err) {
        console.warn(
          "[cron-samples] tick failed:",
          err instanceof Error ? err.message : String(err),
        );
      }
    };
    const now = new Date();
    const next = new Date(Date.UTC(
      now.getUTCFullYear(),
      now.getUTCMonth(),
      now.getUTCDate(),
      3, 0, 0, 0,
    ));
    if (next.getTime() <= now.getTime()) {
      next.setUTCDate(next.getUTCDate() + 1);
    }
    const delayMs = next.getTime() - now.getTime();
    setTimeout(() => {
      cronTick();
      setInterval(cronTick, ONE_DAY_MS);
    }, delayMs);
    console.log(
      `[cron-samples] scheduled first run in ${Math.round(delayMs / 3600000)}h (next 03:00 UTC)`,
    );
  } else {
    console.log("[cron-samples] disabled (no DATABASE_URL — dev mode)");
  }

  /* CSSOS_WAVE102 20260508 — Jing
   * Daily pg_dump → R2 backup at 02:00 UTC (one hour before sample-cron).
   * Shells out to scripts/backup-postgres.mjs so the heavy work happens in
   * a child process and a crashed dump can't take down the API server. */
  if (process.env.DATABASE_URL && process.env.R2_BUCKET) {
    const ONE_DAY_MS = 24 * 60 * 60 * 1000;
    const backupTick = () => {
      try {
        const script = path.resolve(__dirname, "..", "scripts", "backup-postgres.mjs");
        const child = spawn(process.execPath, [script], {
          stdio: ["ignore", "pipe", "pipe"],
          env: process.env,
        });
        child.stdout.on("data", (b) => process.stdout.write(`[backup-cron] ${b}`));
        child.stderr.on("data", (b) => process.stderr.write(`[backup-cron] ${b}`));
        child.on("exit", (code) =>
          console.log(`[backup-cron] child exit code=${code}`),
        );
      } catch (err) {
        console.warn("[backup-cron] spawn failed:", err instanceof Error ? err.message : String(err));
      }
    };
    const nowB = new Date();
    const nextB = new Date(Date.UTC(
      nowB.getUTCFullYear(), nowB.getUTCMonth(), nowB.getUTCDate(), 2, 0, 0, 0,
    ));
    if (nextB.getTime() <= nowB.getTime()) nextB.setUTCDate(nextB.getUTCDate() + 1);
    const bDelay = nextB.getTime() - nowB.getTime();
    setTimeout(() => {
      backupTick();
      setInterval(backupTick, ONE_DAY_MS);
    }, bDelay);
    console.log(
      `[backup-cron] scheduled first run in ${Math.round(bDelay / 3600000)}h (next 02:00 UTC)`,
    );
  } else {
    console.log("[backup-cron] disabled (DATABASE_URL or R2_BUCKET not set)");
  }

  /* CSSOS_PERSON_MV_WAVE93 20260508 — Jing
   * Nightly LLM auto-expand toward 1000 persons. Fires at 04:00 UTC
   * (one hour after sample-cron at 03:00 UTC so they don't collide).
   * Each tick adds up to 30 B-tier persons via diversity-gap LLM.
   * Stops once total persons >= 1000. */
  if (process.env.DATABASE_URL) {
    const ONE_DAY_MS = 24 * 60 * 60 * 1000;
    const expandTick = async () => {
      try {
        const total = await getPersonCount();
        if (total >= 1000) {
          console.log("[bulk-expand] cap reached:", total);
          return;
        }
        const r = await expandTierWithLlm({ tier: "B", count: 30 });
        console.log(
          `[bulk-expand] added ${r.succeeded} of ${r.attempted} (skip=${r.skipped} fail=${r.failed} gaps=${r.gaps.length})`,
        );
      } catch (err) {
        console.error(
          "[bulk-expand] cron error:",
          err instanceof Error ? err.message : String(err),
        );
      }
    };
    const nowExp = new Date();
    const nextExp = new Date(Date.UTC(
      nowExp.getUTCFullYear(),
      nowExp.getUTCMonth(),
      nowExp.getUTCDate(),
      4, 0, 0, 0,
    ));
    if (nextExp.getTime() <= nowExp.getTime()) {
      nextExp.setUTCDate(nextExp.getUTCDate() + 1);
    }
    const expDelay = nextExp.getTime() - nowExp.getTime();
    setTimeout(() => {
      expandTick();
      setInterval(expandTick, ONE_DAY_MS);
    }, expDelay);
    console.log(
      `[bulk-expand] scheduled first run in ${Math.round(expDelay / 3600000)}h (next 04:00 UTC)`,
    );
  } else {
    console.log("[bulk-expand] disabled (no DATABASE_URL — dev mode)");
  }

  /* CSSOS_PERSON_MV_WAVE20 20260508 — Jing
   * Notifications cap-cleanup: keep at most 1000 rows per user. Tick
   * every 12h, no-op when DB is absent. */
  if (process.env.DATABASE_URL) {
    const TWELVE_HOURS_MS = 12 * 60 * 60 * 1000;
    const notifCleanupTick = async () => {
      try {
        const removed = await pruneOldNotifications(1000);
        if (removed > 0) {
          console.log(`[notifications] cleanup pruned ${removed} old row(s)`);
        }
      } catch (err) {
        console.warn(
          "[notifications] cleanup failed (non-fatal):",
          err instanceof Error ? err.message : String(err),
        );
      }
    };
    setTimeout(notifCleanupTick, 10 * 60 * 1000);
    setInterval(notifCleanupTick, TWELVE_HOURS_MS);
  }

  /* CSSOS_PERSON_MV_WAVE33 20260508 — Jing
   * Daily prune of expired GDPR export ZIPs (>7 days). Same-process
   * scheduler — no external cron required. */
  if (process.env.DATABASE_URL) {
    const ONE_DAY_MS = 24 * 60 * 60 * 1000;
    const exportPruneTick = async () => {
      try {
        const removed = await pruneExpiredExports();
        if (removed > 0) console.log(`[export] pruned ${removed} expired zip(s)`);
      } catch (err) {
        console.warn("[export] prune tick failed:", (err as Error)?.message || err);
      }
    };
    setTimeout(exportPruneTick, 15 * 60 * 1000);
    setInterval(exportPruneTick, ONE_DAY_MS);
  }

  /* CSSOS_PERSON_MV_WAVE59 20260508 — Jing — engine health probe scheduler.
   * Probes ~10 engines (image/llm/music classes) every 30 minutes.
   * First run is delayed 2 minutes after boot so the DB pool is warm. */
  if (process.env.DATABASE_URL) {
    const THIRTY_MIN_MS = 30 * 60 * 1000;
    const healthTick = async () => {
      try {
        await engineHealthProbeTick();
      } catch (err) {
        console.warn("[engine-health] tick failed:", (err as Error)?.message || err);
      }
    };
    setTimeout(healthTick, 2 * 60 * 1000);
    setInterval(healthTick, THIRTY_MIN_MS);
  }

  /* CSSOS_PERSON_MV_WAVE60 20260508 — Jing — balance alert scheduler.
   * Polls /api/admin/engine-balance internals every 6h, alerting admin
   * users by notification + web push when an engine balance drops below
   * its threshold (deduped to once per 24h per engine). */
  if (process.env.DATABASE_URL) {
    const SIX_HOURS_MS = 6 * 60 * 60 * 1000;
    const balanceTick = async () => {
      try {
        await balanceAlertTick();
      } catch (err) {
        console.warn("[balance-alerts] tick failed:", (err as Error)?.message || err);
      }
    };
    setTimeout(balanceTick, 5 * 60 * 1000);
    setInterval(balanceTick, SIX_HOURS_MS);
  }

  /* CSSOS_PERSON_MV_WAVE78 20260508 — Jing — weekly email digest.
   * Same-process scheduler; fires every Monday 09:00 UTC. Each tick
   * pulls users with email_digest_enabled=true, verified email, and
   * email_digest_last_sent_at older than 6 days, then sends at 10/sec
   * to avoid SMTP/Resend throttle. */
  if (process.env.DATABASE_URL) {
    const { weeklyDigestTick } = await import("./lib/weekly-digest");
    const ONE_WEEK_MS = 7 * 24 * 60 * 60 * 1000;
    const ONE_HOUR_MS = 60 * 60 * 1000;
    const APP_BASE = (process.env.APP_BASE_URL || "https://cssos.app").replace(/\/+$/, "");
    const digestTick = async () => {
      try {
        const summary = await weeklyDigestTick(APP_BASE);
        console.log(
          `[digest] weekly tick — considered=${summary.considered} sent=${summary.sent} failed=${summary.failed} skipped=${summary.skipped}`,
        );
      } catch (err) {
        console.warn("[digest] weekly tick failed:", (err as Error)?.message || err);
      }
    };
    const now = new Date();
    const next = new Date(Date.UTC(
      now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 9, 0, 0, 0,
    ));
    const dayDelta = (1 - next.getUTCDay() + 7) % 7;
    next.setUTCDate(next.getUTCDate() + dayDelta);
    if (next.getTime() <= now.getTime()) next.setUTCDate(next.getUTCDate() + 7);
    const delayMs = next.getTime() - now.getTime();
    setTimeout(() => {
      digestTick();
      setInterval(digestTick, ONE_WEEK_MS);
    }, delayMs);
    console.log(
      `[digest] scheduled first run in ${Math.round(delayMs / ONE_HOUR_MS)}h (next Mon 09:00 UTC)`,
    );
  }

  /* CSSOS_WAVE94 20260508 — Jing — synthetic site-health probes.
   * HTTP + DB probes every 15 min; canary MV every 6 hours. All
   * fire-and-forget; errors swallowed in lib via logProbe(). */
  if (process.env.DATABASE_URL) {
    const FIFTEEN_MIN_MS = 15 * 60 * 1000;
    const SIX_HOURS_MS = 6 * 60 * 60 * 1000;
    const fastTick = async () => {
      try {
        const { runHttpHealthProbes, runDbQueryProbes } = await import("./lib/health-probes");
        await Promise.allSettled([runHttpHealthProbes(), runDbQueryProbes()]);
      } catch (err) {
        console.warn("[health-probe] fast tick failed:", (err as Error)?.message || err);
      }
    };
    const canaryTick = async () => {
      try {
        if (process.env.CSSOS_DISABLE_CANARY_MV === "1") return;
        const { runCanaryMv } = await import("./lib/health-probes");
        const systemUserId = await resolveSystemUserId();
        await runCanaryMv(
          async (person, opts) => {
            const r = await runHeadlessPipeline(person, opts);
            return { ok: !!r.ok, stages: r.stages, error: r.error };
          },
          systemUserId,
        );
      } catch (err) {
        console.warn("[canary-mv] tick failed:", (err as Error)?.message || err);
      }
    };
    setTimeout(fastTick, 90 * 1000);
    setInterval(fastTick, FIFTEEN_MIN_MS);
    setTimeout(canaryTick, 10 * 60 * 1000);
    setInterval(canaryTick, SIX_HOURS_MS);
    console.log("[health-probe] schedulers armed (HTTP+DB 15m, canary 6h)");
  }

  /* CSSOS_WAVE99 20260508 — Jing — daily OPS report.
   * Fires daily at 09:00 UTC (same cadence as digest). Skips when no
   * email transport is configured. */
  if (process.env.DATABASE_URL) {
    const ONE_DAY_MS = 24 * 60 * 60 * 1000;
    const opsTick = async () => {
      try {
        const { sendDailyOpsReport } = await import("./lib/daily-ops-report");
        const out = await sendDailyOpsReport();
        console.log(
          `[ops-report] daily — sent=${out.sent} skipped=${out.skipped} errors=${out.errors.length}${out.reason ? " reason=" + out.reason : ""}`,
        );
      } catch (err) {
        console.warn("[ops-report] daily tick failed:", (err as Error)?.message || err);
      }
    };
    const now = new Date();
    const next = new Date(Date.UTC(
      now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 9, 0, 0, 0,
    ));
    if (next.getTime() <= now.getTime()) next.setUTCDate(next.getUTCDate() + 1);
    const delayMs = next.getTime() - now.getTime();
    setTimeout(() => {
      opsTick();
      setInterval(opsTick, ONE_DAY_MS);
    }, delayMs);
    console.log(
      `[ops-report] scheduled first run in ${Math.round(delayMs / (60 * 60 * 1000))}h (daily 09:00 UTC)`,
    );
  }

  /* CSSOS_WAVE100 20260508 — Jing — daily TLS / cert monitor.
   * Fires at 06:00 UTC. Fire-and-forget; logs results, alerts admins
   * when any cert has <14 days remaining. */
  if (process.env.DATABASE_URL) {
    const ONE_DAY_MS = 24 * 60 * 60 * 1000;
    const tlsTick = async () => {
      try {
        const out = await tlsMonitorTick();
        console.log(
          `[tls-monitor] daily — checked=${out.checked} alerts=${out.alerts} expiring=${out.expiring.length}`,
        );
      } catch (err) {
        console.warn("[tls-monitor] daily tick failed:", (err as Error)?.message || err);
      }
    };
    const now = new Date();
    const next = new Date(Date.UTC(
      now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), 6, 0, 0, 0,
    ));
    if (next.getTime() <= now.getTime()) next.setUTCDate(next.getUTCDate() + 1);
    const delayMs = next.getTime() - now.getTime();
    setTimeout(() => {
      tlsTick();
      setInterval(tlsTick, ONE_DAY_MS);
    }, delayMs);
    console.log(
      `[tls-monitor] scheduled first run in ${Math.round(delayMs / (60 * 60 * 1000))}h (daily 06:00 UTC)`,
    );
  }

  /* CSSOS_PERSON_MV_WAVE43 20260508 — Jing — WebSocket migration.
   * Boot a WebSocketServer on the same HTTP server. Three channels
   * (live rooms, collab sessions, watch parties). Auth parses the
   * express-session cookie from the upgrade request and rejects
   * anonymous. Long-poll routes remain as fallback. */
  // CSSOS_PERSON_MV_WAVE63 — added "dm" channel for /ws/dm/:thread_id.
  type WsChannel = "live" | "collab" | "party" | "dm";
  const wsHubs: Record<WsChannel, Map<string, Set<WebSocket>>> = {
    live: new Map(), collab: new Map(), party: new Map(), dm: new Map(),
  };
  function wsPublish(channel: WsChannel, channelId: string, msg: unknown): void {
    try {
      const set = wsHubs[channel].get(channelId);
      if (!set || set.size === 0) return;
      const data = typeof msg === "string" ? msg : JSON.stringify(msg);
      for (const sock of set) {
        if (sock.readyState === WebSocket.OPEN) {
          try { sock.send(data); } catch { /* ignore */ }
        }
      }
    } catch { /* ignore */ }
  }
  (globalThis as any).__cssosWsPublish = wsPublish;

  // CSSOS_WAVE82 20260508 — global error handler logs to server_error_log
  // before delegating to Sentry. Uses logServerError() which fire-and-forgets.
  app.use((err: any, req: any, _res: any, next: any) => {
    try {
      const path = String(req?.originalUrl || req?.url || "").slice(0, 400);
      const source: import("./observability").ServerErrorSource =
        path.startsWith("/api/stripe") || path.includes("/payment") ? "payment"
          : path.startsWith("/api/auth") ? "auth"
          : path.startsWith("/api/engine") || path.includes("/engines/") ? "engine"
          : path.startsWith("/api/mv") || path.includes("/pipeline") ? "pipeline"
          : "http";
      logServerError("error", source, err, {
        user_id: (req?.session && req.session.user_id) || null,
        request_path: path,
      });
    } catch { /* swallow */ }
    next(err);
  });

  // CSSOS_WAVE80 20260508 — Sentry express error handler (no-op when DSN unset).
  // Registered late so route handlers above can short-circuit normally and only
  // *unhandled* errors flow into Sentry.
  attachSentryErrorHandler(app);

  const httpServer = http.createServer(app);
  const wss = new WebSocketServer({ noServer: true });
  const sessionMw = session(sessionConfig);

  httpServer.on("upgrade", (req, socket, head) => {
    try {
      const url = req.url || "";
      const m = url.match(/^\/ws\/(live|collab|party|dm)\/([A-Za-z0-9_\-]+)/);
      if (!m) {
        socket.write("HTTP/1.1 404 Not Found\r\n\r\n"); socket.destroy(); return;
      }
      const channel = m[1] as WsChannel;
      const channelId = String(m[2] || "");
      const fakeRes: any = { on() {}, end() {}, setHeader() {}, getHeader() {}, writeHead() {} };
      sessionMw(req as any, fakeRes, () => {
        const uid = ((req as any).session && (req as any).session.user_id) || null;
        if (!uid) {
          socket.write("HTTP/1.1 401 Unauthorized\r\n\r\n"); socket.destroy(); return;
        }
        wss.handleUpgrade(req, socket as any, head, (ws) => {
          let set = wsHubs[channel].get(channelId);
          if (!set) { set = new Set(); wsHubs[channel].set(channelId, set); }
          set.add(ws);
          try { ws.send(JSON.stringify({ ok: true, channel, channel_id: channelId })); } catch {}
          ws.on("close", () => {
            const s = wsHubs[channel].get(channelId);
            if (s) { s.delete(ws); if (s.size === 0) wsHubs[channel].delete(channelId); }
          });
          ws.on("error", () => { /* ignore */ });
        });
      });
    } catch {
      try { socket.destroy(); } catch {}
    }
  });

  httpServer.listen(PORT, () => {
    console.log(`cssOS API running on http://localhost:${PORT}`);
    console.log(`[ws] hub ready: /ws/{live|collab|party|dm}/:id`);
    // Tier-fallback sanity log — surfaces misconfigured order at boot.
    const fmt = (ps: string[]) => ps.map((p) => `${p}(${providerTier(p)})`).join(" → ");
    console.log(`[engines] image order: ${fmt(imageProviderOrder())}`);
    console.log(`[engines] video order: ${fmt(videoProviderOrder())}`);
    console.log(`[engines] music order: ${fmt(musicProviderOrder())}`);
    console.log(`[engines] llm   order: ${fmt(llmProviderOrder() as string[])}`);
    console.log(`[engines] tts   order: ${fmt(ttsProviderOrder())}`);
  });
}

